{"path": "/tmp/sv-587d348b30e14f619b28c844d8d5b094/RecipeCommunity/Services/RecipeService.cs", "file_text": "using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes = new List<Recipe>
        {
            new() { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt",
                Steps = "1. Preheat oven to 475°F (245°C).\n2. Roll out dough on a floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute over sauce.\n5. Bake for 10-12 minutes until crust is golden.\n6. Top with fresh basil and a drizzle of olive oil.",
                TotalStars = 14, RatingCount = 3 },
            new() { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
                Ingredients = "Spaghetti\nGuanciale (or pancetta)\nEgg yolks\nPecorino Romano\nBlack pepper",
                Steps = "1. Cook spaghetti in salted boiling water until al dente.\n2. Crisp guanciale in a pan over medium heat.\n3. Whisk egg yolks with grated Pecorino and pepper.\n4. Toss hot pasta with guanciale, remove from heat.\n5. Stir in egg mixture quickly, tossing to coat without scrambling.",
                TotalStars = 10, RatingCount = 2 },
            new() { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
                Ingredients = "Chicken thighs\nYogurt\nGaram masala\nTurmeric\nCumin\nCrushed tomatoes\nHeavy cream\nOnion\nGarlic\nGinger",
                Steps = "1. Marinate chicken in yogurt and spices for at least 1 hour.\n2. Grill or broil chicken until charred.\n3. Sauté onion, garlic, and ginger in a pan.\n4. Add crushed tomatoes and simmer 15 minutes.\n5. Stir in cream, add chicken, simmer 10 more minutes.\n6. Serve over basmati rice.",
                TotalStars = 5, RatingCount = 1 },
            new() { Id = 4, Title = "Vegetable Pad Thai", Category = "Asian",
                Ingredients = "Rice noodles\nTofu\nBean sprouts\nGreen onions\nPeanuts\nLime\nFish sauce\nTamarind paste\nBrown sugar\nGarlic",
                Steps = "1. Soak rice noodles in warm water for 20 minutes.\n2. Press and cube tofu, fry until golden.\n3. Mix tamarind paste, fish sauce, and brown sugar for sauce.\n4. Stir-fry garlic, add noodles and sauce.\n5. Toss with bean sprouts and green onions.\n6. Serve with crushed peanuts and lime wedges.",
                TotalStars = 8, RatingCount = 2 },
            new() { Id = 5, Title = "Beef Tacos", Category = "Mexican",
                Ingredients = "Ground beef\nTaco seasoning\nCorn tortillas\nLettuce\nTomato\nCheddar cheese\nSour cream\nSalsa",
                Steps = "1. Brown ground beef in a skillet over medium-high heat.\n2. Add taco seasoning and water, simmer until thickened.\n3. Warm tortillas in a dry pan or microwave.\n4. Fill tortillas with seasoned beef.\n5. Top with lettuce, tomato, cheese, sour cream, and salsa.",
                TotalStars = 12, RatingCount = 3 },
            new() { Id = 6, Title = "Guacamole", Category = "Mexican",
                Ingredients = "Avocados\nLime juice\nRed onion\nCilantro\nJalapeño\nTomato\nSalt",
                Steps = "1. Halve and pit avocados, scoop into a bowl.\n2. Mash with a fork to desired consistency.\n3. Stir in diced onion, tomato, jalapeño, and cilantro.\n4. Add lime juice and salt to taste.\n5. Serve immediately with tortilla chips.",
                TotalStars = 9, RatingCount = 2 },
            new() { Id = 7, Title = "Chocolate Chip Cookies", Category = "Desserts",
                Ingredients = "Butter\nSugar\nBrown sugar\nEggs\nVanilla extract\nAll-purpose flour\nBaking soda\nSalt\nChocolate chips",
                Steps = "1. Preheat oven to 375°F (190°C).\n2. Cream butter with both sugars until fluffy.\n3. Beat in eggs and vanilla.\n4. Mix in flour, baking soda, and salt.\n5. Fold in chocolate chips.\n6. Drop spoonfuls onto baking sheets.\n7. Bake 9-11 minutes until edges are golden.",
                TotalStars = 15, RatingCount = 3 },
            new() { Id = 8, Title = "Miso Soup", Category = "Asian",
                Ingredients = "Dashi stock\nWhite miso paste\nSilken tofu\nWakame seaweed\nGreen onions",
                Steps = "1. Bring dashi stock to a gentle simmer.\n2. Rehydrate wakame in water, drain.\n3. Cube silken tofu.\n4. Remove pot from heat, whisk in miso paste.\n5. Add tofu and wakame.\n6. Garnish with sliced green onions.",
                TotalStars = 4, RatingCount = 1 },
        };
        _nextId = 9;
    }

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public IReadOnlyList<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalStars += stars;
            recipe.RatingCount++;
        }
    }

    public Recipe AddRecipe(string title, string category, string ingredients, string steps)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps
        };
        _recipes.Add(recipe);
        return recipe;
    }
}
"}

