@page "/category/{CategoryName}"
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@CategoryName</li>
    </ol>
</nav>

<h1>@CategoryName Recipes</h1>

@if (recipes.Count == 0)
{
    <div class="alert alert-info">No recipes found in this category.</div>
}
else
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-4 mb-4">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="text-muted">
                            @if (recipe.RatingCount > 0)
                            {
                                <span>⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)</span>
                            }
                            else
                            {
                                <span>No ratings yet</span>
                            }
                        </p>
                    </div>
                    <div class="card-footer">
                        <a href="/recipe/@recipe.Id" class="btn btn-primary btn-sm">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;

    private IReadOnlyList<RecipeCommunity.Models.Recipe> recipes = [];

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe Not Found")</PageTitle>

@if (recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/category/@recipe.Category">@recipe.Category</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h1>@recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@recipe.Category</span>

    <div class="mb-3">
        @if (recipe.RatingCount > 0)
        {
            <span>⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)</span>
        }
        else
        {
            <span class="text-muted">No ratings yet</span>
        }
    </div>

    <StarRating RecipeId="recipe.Id" @rendermode="InteractiveServer" />

    <div class="row mt-4">
        <div class="col-md-5">
            <div class="card">
                <div class="card-header"><h4 class="mb-0">Ingredients</h4></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>
        <div class="col-md-7">
            <div class="card">
                <div class="card-header"><h4 class="mb-0">Steps</h4></div>
                <div class="card-body">
                    @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <p>@step</p>
                    }
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }

    private RecipeCommunity.Models.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetById(Id);
    }
}

@using RecipeCommunity.Services
@inject RecipeService RecipeService

<div class="my-2">
    <strong>Rate this recipe:</strong>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="btn btn-sm @(star <= (hoverStar ?? selectedStar) ? "btn-warning" : "btn-outline-secondary")"
                style="font-size: 1.3rem; padding: 2px 6px; border: none; cursor: pointer;"
                @onmouseover="() => hoverStar = star"
                @onmouseout="() => hoverStar = null"
                @onclick="() => SubmitRating(star)"
                disabled="@submitted">
            ★
        </button>
    }
    @if (submitted)
    {
        <span class="text-success ms-2">✓ Thanks for rating!</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }

    private int selectedStar;
    private int? hoverStar;
    private bool submitted;

    private void SubmitRating(int stars)
    {
        if (submitted) return;
        selectedStar = stars;
        submitted = true;
        RecipeService.AddRating(RecipeId, stars);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeCommunity.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">Submit Recipe</li>
    </ol>
</nav>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (!string.IsNullOrEmpty(successMessage))
{
    <div class="alert alert-success">@successMessage</div>
}

@if (!string.IsNullOrEmpty(errorMessage))
{
    <div class="alert alert-danger">@errorMessage</div>
}

<div class="card shadow-sm">
    <div class="card-body">
        <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
            <DataAnnotationsValidator />
            <ValidationSummary class="text-danger" />

            <div class="mb-3">
                <label for="title" class="form-label">Recipe Title</label>
                <InputText id="title" class="form-control" @bind-Value="model.Title" placeholder="e.g. Grandma's Apple Pie" />
            </div>

            <div class="mb-3">
                <label for="category" class="form-label">Category</label>
                <InputSelect id="category" class="form-select" @bind-Value="model.Category">
                    <option value="">-- Select a category --</option>
                    <option value="Italian">Italian</option>
                    <option value="Indian">Indian</option>
                    <option value="Asian">Asian</option>
                    <option value="Mexican">Mexican</option>
                    <option value="Desserts">Desserts</option>
                    <option value="Other">Other</option>
                </InputSelect>
            </div>

            <div class="mb-3">
                <label for="ingredients" class="form-label">Ingredients (one per line)</label>
                <InputTextArea id="ingredients" class="form-control" rows="6" @bind-Value="model.Ingredients"
                               placeholder="2 cups flour&#10;1 cup sugar&#10;3 apples, sliced" />
            </div>

            <div class="mb-3">
                <label for="steps" class="form-label">Steps (one per line)</label>
                <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="model.Steps"
                               placeholder="1. Preheat oven to 350°F.&#10;2. Mix dry ingredients.&#10;3. ..." />
            </div>

            <button type="submit" class="btn btn-success">Submit Recipe</button>
        </EditForm>
    </div>
</div>

@code {
    private RecipeFormModel model = new();
    private string? successMessage;
    private string? errorMessage;

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(model.Title) ||
            string.IsNullOrWhiteSpace(model.Category) ||
            string.IsNullOrWhiteSpace(model.Ingredients) ||
            string.IsNullOrWhiteSpace(model.Steps))
        {
            errorMessage = "Please fill in all fields.";
            successMessage = null;
            return;
        }

        var recipe = RecipeService.AddRecipe(model.Title, model.Category, model.Ingredients, model.Steps);
        successMessage = $"Recipe \"{recipe.Title}\" submitted successfully!";
        errorMessage = null;
        model = new();
    }

    private class RecipeFormModel
    {
        public string Title { get; set; } = string.Empty;
        public string Category { get; set; } = string.Empty;
        public string Ingredients { get; set; } = string.Empty;
        public string Steps { get; set; } = string.Empty;
    }
}

